def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    me_last, op_last = history[-1]

    op_c = 0
    after_my_c = 0
    after_my_c_c = 0
    after_my_d = 0
    after_my_d_c = 0
    unprovoked_total = 0

    for i in range(n):
        m, o = history[i]
        if o == 'C':
            op_c += 1
        if i > 0:
            pm = history[i - 1][0]
            if pm == 'C':
                after_my_c += 1
                if o == 'C':
                    after_my_c_c += 1
            else:
                after_my_d += 1
                if o == 'C':
                    after_my_d_c += 1
        prev = history[i - 1][0] if i > 0 else 'C'
        if o == 'D' and prev == 'C':
            unprovoked_total += 1

    recent_len = min(12, n)
    recent_op_c = 0
    for i in range(n - recent_len, n):
        if history[i][1] == 'C':
            recent_op_c += 1
    recent_op_d = recent_len - recent_op_c

    recent8_len = min(8, n)
    recent8_op_c = 0
    for i in range(n - recent8_len, n):
        if history[i][1] == 'C':
            recent8_op_c += 1

    recent_after_my_c = 0
    recent_after_my_c_c = 0
    recent_after_my_d = 0
    recent_after_my_d_c = 0
    for i in range(max(1, n - 12), n):
        pm = history[i - 1][0]
        cur = history[i][1]
        if pm == 'C':
            recent_after_my_c += 1
            if cur == 'C':
                recent_after_my_c_c += 1
        else:
            recent_after_my_d += 1
            if cur == 'C':
                recent_after_my_d_c += 1

    recent8_after_my_c = 0
    recent8_after_my_c_c = 0
    for i in range(max(1, n - 8), n):
        if history[i - 1][0] == 'C':
            recent8_after_my_c += 1
            if history[i][1] == 'C':
                recent8_after_my_c_c += 1

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    unprovoked_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            prev = history[i - 1][0] if i > 0 else 'C'
            if prev == 'C':
                unprovoked_streak += 1
            else:
                break
        else:
            break

    my_c_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'C':
            my_c_streak += 1
        else:
            break

    opp_d_in_my_c_streak = 0
    if my_c_streak > 0:
        for i in range(n - my_c_streak, n):
            if history[i][1] == 'D':
                opp_d_in_my_c_streak += 1

    last_d = -1
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            last_d = i
            break
    rounds_since_my_D = n - 1 - last_d if last_d >= 0 else n + 1

    op_rate = op_c / float(n)
    recent_rate = recent_op_c / float(recent_len)
    recent8_rate = recent8_op_c / float(recent8_len) if recent8_len > 0 else 0.0

    p_cc = recent_after_my_c_c / float(recent_after_my_c) if recent_after_my_c > 0 else recent_rate
    p_cc8 = recent8_after_my_c_c / float(recent8_after_my_c) if recent8_after_my_c > 0 else recent8_rate
    p_dc = recent_after_my_d_c / float(recent_after_my_d) if recent_after_my_d > 0 else 0.0

    hard = False
    if recent_len >= 10 and recent_op_c <= 2 and recent_op_d >= recent_len - 3 and p_cc < 0.25:
        hard = True
    if recent8_len >= 8 and recent8_op_c <= 1 and p_cc8 < 0.25:
        hard = True
    if n >= 10 and my_c_streak >= 3 and opp_d_in_my_c_streak == my_c_streak and recent_op_c == 0 and p_cc == 0.0:
        hard = True
    if opp_d_streak >= 15 and recent_op_c == 0:
        hard = True

    if op_last == 'C':
        if recent_after_my_d_c >= 1 and p_dc >= 0.6 and recent_rate >= 0.5 and op_rate >= 0.35:
            return 'D'
        if (
            unprovoked_total >= 3 and
            recent_op_c == recent_len and
            recent_len >= 10 and
            recent_after_my_d == 0 and
            rounds_since_my_D >= 10 and
            rng.random() < 0.025
        ):
            return 'D'
        return 'C'

    if hard:
        if me_last == 'D':
            if rng.random() < 0.04:
                return 'C'
            return 'D'
        if my_c_streak <= 2:
            return 'C'
        return 'D'

    if me_last == 'D':
        return 'C'

    if rounds_since_my_D <= 2:
        if not (my_c_streak >= 3 and opp_d_in_my_c_streak == my_c_streak):
            return 'C'

    if opp_d_streak >= 4 and op_rate >= 0.55 and recent_rate >= 0.4:
        return 'C'

    if unprovoked_streak >= 3 and recent_rate >= 0.5 and p_cc >= 0.5:
        return 'C'

    return 'D'
